from solution import drop_empty


def test_issue_example():
    """Example: drop_empty({'c1':'Red','c2':'Green','c3':None}) keeps Red/Green."""
    result = drop_empty({'c1': 'Red', 'c2': 'Green', 'c3': None})
    # 3 items - 1 None = 2 items
    assert result == {'c1': 'Red', 'c2': 'Green'}


def test_issue_empty_dict():
    """Drop empty items from empty dict gives empty dict."""
    result = drop_empty({})
    # 0 items - 0 dropped = 0 items
    assert result == {}


def test_issue_all_none():
    """Drop empty items removes all entries when all values are None."""
    result = drop_empty({'a': None, 'b': None})
    # 2 items - 2 None = 0 items
    assert result == {}


def test_issue_no_none():
    """Drop empty items keeps every entry when no value is None."""
    result = drop_empty({'c1': 'Red', 'c2': 'Green'})
    # 2 items - 0 None = 2 items
    assert result == {'c1': 'Red', 'c2': 'Green'}


def test_issue_single_none():
    """Drop empty items drops a single None entry."""
    result = drop_empty({'only': None})
    # 1 item - 1 None = 0 items
    assert result == {}


def test_issue_single_kept():
    """Drop empty items keeps a single non-empty string entry."""
    result = drop_empty({'only': 'Blue'})
    # 1 item - 0 None = 1 item
    assert result == {'only': 'Blue'}


def test_issue_multiple_mixed():
    """Drop empty items drops each None among mixed string entries."""
    result = drop_empty({'a': 'x', 'b': None, 'c': 'y', 'd': None, 'e': 'z'})
    # 5 items - 2 None = 3 items
    assert result == {'a': 'x', 'c': 'y', 'e': 'z'}


def test_issue_no_none_in_result():
    """Drop empty items leaves no None value in the result."""
    result = drop_empty({'c1': 'Red', 'c2': None, 'c3': 'Green', 'c4': None})
    # 4 items - 2 None = 2 items, 0 None left (2 - 2 = 0)
    assert all(v is not None for v in result.values())


def test_contract_returns_dict():
    """Function must return a dict for a given dict."""
    result = drop_empty({'c1': 'Red', 'c3': None})
    # 2 items - 1 None = 1 item in a dict
    assert isinstance(result, dict)


def test_contract_keys_subset():
    """Dropping means result keys are a subset of input keys."""
    result = drop_empty({'a': 'x', 'b': None, 'c': 'y'})
    # 3 keys - 1 dropped = 2 keys, 2 <= 3
    assert set(result.keys()) <= {'a', 'b', 'c'}


def test_contract_values_preserved():
    """Dropping means kept values are unchanged from input."""
    result = drop_empty({'k1': 'Red', 'k2': None, 'k3': 'Green'})
    # 3 items - 1 None = 2 items with same values
    assert result == {'k1': 'Red', 'k3': 'Green'}
